head.script:
scwin.onpageload = function() {
    // 모달 초기화
    scwin.initModal();
};

scwin.modalClose = function(argRuntimeID) {
    try {
        // 팝업 객체 접근
        let popObj = $p.getPopupWindow(argRuntimeID);

        // 모달 상태 초기화
        scwin.modalManager.isModalOpen = false;
        scwin.modalManager.modalInstance = null;

        console.log("팝업 닫기 액션 완료");

        return true; // 팝업 닫기 허용

    } catch (e) {
        console.error("팝업 닫기 액션 오류:", e);

        // 오류가 있어도 레이아웃과 모달 상태는 초기화
        scwin.modalManager.isModalOpen = false;
        scwin.modalManager.modalInstance = null;

        return true; // 팝업 닫기 허용
    }
}

// 모달 초기화
scwin.initModal = function() {
    try {
        // 팝업 파라미터에서 userName 가져오기 - dataObject 방식
        let popupParam = $p.getParameter("project_param");
        let userName = "식스센스"; // 기본값
        if (popupParam && popupParam.userName) {
            userName = popupParam.userName;
            console.log("팝업 파라미터에서 팀장명 가져옴:", userName);
        } else {
            console.log("팝업 파라미터가 없어 기본값 사용:", userName);
        }

        // 팀장 인풋을 읽기전용으로 설정
        if (input_userName) {
            input_userName.setValue(userName);
            input_userName.setReadOnly(true);
        }

        console.log("프로젝트 추가 모달 초기화 완료 - 팀장:", userName);
    } catch(e) {
        console.error("모달 초기화 오류:", e);
        // 오류 발생 시 기본값 설정 - ProjectVo에 맞추어 모든 필드 초기화
        dm_projectForm.set("projectId", "");
        dm_projectForm.set("projectName", "2차 프로젝트");
        dm_projectForm.set("description", "");
        dm_projectForm.set("projectImageUrl", "");
        dm_projectForm.set("createdAt", "");
        dm_projectForm.set("emailSendTime", "");
        dm_projectForm.set("userId", "");
        dm_projectForm.set("userName", "식스센스");
        dm_projectForm.set("hour", "00");
        dm_projectForm.set("minute", "00");

        if (input_userName) {
            input_userName.setReadOnly(true);
        }
    }
};

// 저장 버튼 클릭
scwin.btn_save_onclick = function(e) {
    try {
        let projectName = dm_projectForm.get("projectName");
        // let userName = dm_projectForm.get("userName");
        let popupParam = $p.getParameter("project_param");
        // let modalId = $p.parent().scwin.modalManager.modalId;
        if (!projectName || projectName.trim() === "") {
            alert("프로젝트명을 입력해주세요.");
            return;
        }

        // hour와 minute를 조립해서 emailSendTime에 설정
        const hour = scwin.validateTimeInput(input_hour.getValue(), 23);
        const minute = scwin.validateTimeInput(input_minute.getValue(), 59);
        const emailSendTime = hour + ":" + minute;
        dm_projectForm.set("emailSendTime", emailSendTime);
        console.log(emailSendTime);
        dm_projectForm.set("userId",popupParam.userId);
        console.log(popupParam.userId);
        dm_projectForm.set("description",input_description.getValue());

        // 서브미션 실행 (다시 활성화)
        $c.sbm.execute(sbm_saveProject);



        // scwin.modalClose(scwin.modalId,modalArgJsnInfo);
        // scwin.modalClose(scwin.modalId);
    } catch(e) {
        console.error("프로젝트 저장 오류:", e);
        alert("프로젝트 저장 중 오류가 발생했습니다.");
        scwin.modalClose(scwin.modalId,modalArgJsnInfo);
    }
};

// 서브미션 성공 시 처리
scwin.sbm_saveProject_submitdone = function(e) {
    try {
        // 서버 응답 검증
        const elHeader = e.responseJSON && e.responseJSON.elHeader;
        if (elHeader && elHeader.resSuc === false) {
            alert("에러코드: " + elHeader.resCode + "\n에러메시지: " + elHeader.resMsg);
            return;
        }

        alert("프로젝트가 성공적으로 저장되었습니다!");

        // 부모 창의 refreshSideMenu 함수 호출 (사이드메뉴 새로고침)
        const parentFrame = $p.parent();
        if (parentFrame && parentFrame.scwin && parentFrame.scwin.refreshSideMenu) {
            parentFrame.scwin.refreshSideMenu();
        }

        // WebSquare 팝업 닫기 - 여러 방법 시도
        console.log("팝업 닫기 시도 시작");

        try {
            // 방법 1: WebSquare 공식 API
            if (typeof $p.closePopup === 'function') {
                console.log("방법 1: $p.closePopup() 사용");
                $p.closePopup();
            } 
        } catch (closeError) {
            console.error("팝업 닫기 오류:", closeError);
        }

    } catch (error) {
        console.error("서브미션 완료 처리 중 오류:", error);
        alert("프로젝트가 저장되었지만 화면 처리 중 오류가 발생했습니다.");

        // 오류가 발생해도 팝업은 닫기 시도
        try {
            if (typeof $p.closePopup === 'function') {
                $p.closePopup();
            } else if (window.close) {
                window.close();
            }
        } catch (closeError) {
            console.warn("팝업 닫기 실패:", closeError);
        }
    }
};

// 서브미션 실패 시 처리
scwin.sbm_saveProject_submiterror = function(e) {
    console.error("프로젝트 저장 실패:", e);
    alert("프로젝트 저장 중 오류가 발생했습니다. 다시 시도해주세요.");
};

// 이름 입력 키보드 이벤트
scwin.input_name_onkeyup = function(e) {
    dm_projectForm.set("projectName", e.target.value);
};

// 시간 입력 검증
scwin.validateTimeInput = function(inputValue, maxValue) {
    const num = parseInt(inputValue);
    if (isNaN(num) || num < 0) {
        return "00";
    } else if (num > maxValue) {
        return String(maxValue).padStart(2, '0');
    } else {
        return String(num).padStart(2, '0');
    }
};
